// src/app/core/guards/auth.guard.ts
var authGuard = () => {
  const auth = inject2(AuthService);
  const router = inject2(Router);
  if (auth.estConnecte()) {
    return true;
  }
  return router.createUrlTree(["/connexion"]);
};

// src/app/core/guards/admin.guard.ts
var adminSystemeGuard = () => {
  const auth = inject2(AuthService);
  const router = inject2(Router);
  if (auth.utilisateur()?.role === "admin_systeme") {
    return true;
  }
  return router.createUrlTree(["/admin/dashboard"]);
};

// src/app/app.routes.ts
var routes = [
  { path: "", redirectTo: "connexion", pathMatch: "full" },
  { path: "connexion", component: LoginComponent, title: "Connexion \u2014 Espace d\u2019administration DU" },
  {
    path: "admin",
    component: AdminLayoutComponent,
    canActivate: [authGuard],
    children: [
      { path: "", redirectTo: "dashboard", pathMatch: "full" },
      { path: "dashboard", component: DashboardComponent, title: "Tableau de bord \u2014 DU" },
      { path: "dossiers", component: DossierListComponent, title: "Dossiers \u2014 DU" },
      { path: "dossiers/nouveau", component: DossierFormComponent, title: "Nouveau dossier \u2014 DU" },
      { path: "dossiers/:id", component: DossierDetailComponent, title: "D\xE9tail dossier \u2014 DU" },
      {
        path: "dossiers/:id/modifier",
        component: DossierFormComponent,
        title: "Modifier dossier \u2014 DU"
      },
      { path: "mouvements", component: MouvementsComponent, title: "Mouvements \u2014 DU" },
      { path: "localisations", component: LocalisationsComponent, title: "Localisations \u2014 DU" },
      { path: "documents", component: DocumentsComponent, title: "Documents \u2014 DU" },
      { path: "utilisateurs", component: UtilisateursComponent, title: "Utilisateurs \u2014 DU", canActivate: [adminSystemeGuard] },
      { path: "canevas-excel", component: CanevasExcelComponent, title: "Canevas Excel \u2014 DU" },
      { path: "parametres", component: ParametresComponent, title: "Param\xE8tres \u2014 DU" }
    ]
  },
  { path: "**", redirectTo: "connexion" }
];

// src/app/core/interceptors/auth.interceptor.ts
var authInterceptor = (requete, suivant) => {
  const auth = inject2(AuthService);
  const router = inject2(Router);
  const jeton = auth.token();
  const requeteAuth = jeton ? requete.clone({ setHeaders: { Authorization: `Bearer ${jeton}` } }) : requete;
  return suivant(requeteAuth).pipe(
    catchError((erreur) => {
      if (erreur.status === 401 && auth.estConnecte()) {
        auth.purger();
        void router.navigate(["/connexion"]);
      }
      return throwError(() => erreur);
    })
  );
};

